mapper.select:
SELECT g.id, g.name, g.cover, ranked.play_time AS playTime FROM (
SELECT game_id, play_time FROM user_games WHERE user_id = #{userId}
SELECT game_id, SUM(duration) AS play_time FROM play_records WHERE user_id = #{userId}
AND start_time >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)
AND start_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
GROUP BY game_id
) ranked JOIN games g ON ranked.game_id = g.id ORDER BY ranked.play_time DESC LIMIT #{limit}

SELECT COALESCE(SUM(play_time), 0)
FROM user_games
WHERE user_id = #{userId}
